```cpp
#include <iostream>
using namespace std;

int main() {
    double side_length;

    // Prompt the user to enter the side length of the square
    cout << "Enter the length of one side of the square: ";
    cin >> side_length;

    // Calculate the perimeter
    double perimeter = 4 * side_length;

    // Display the result
    cout << "The perimeter of the square is: " << perimeter << endl;

    return 0;
}
```

